import {ActionList} from '@primer/react'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {getSessionStatusIcon} from '../StatusIcon'
import type {Session} from '../../types/session'
import styles from './SessionsNav.module.css'
import SessionElapsedTime from '../SessionElapsedTime'
import {AlertIcon, InfoIcon} from '@primer/octicons-react'
import pluralize from 'pluralize'

interface SessionListProps {
  sessionsData: Session[] | undefined
  sessionsIsLoading: boolean
  onSessionChange: (id: string) => void
  activeSessionId: string
}

interface SessionsNavProps extends SessionListProps {
  sessionsIsError: boolean
}

const SessionList = ({sessionsIsLoading, sessionsData, onSessionChange, activeSessionId}: SessionListProps) => {
  if (sessionsIsLoading || !sessionsData) {
    return (
      <>
        <ActionList.Item role="status">
          <LoadingSkeleton variant="rounded" className={styles.loadingSession} />
        </ActionList.Item>
        <ActionList.Item role="status">
          <LoadingSkeleton variant="rounded" className={styles.loadingSession} />
        </ActionList.Item>
        <ActionList.Item role="status">
          <LoadingSkeleton variant="rounded" className={styles.loadingSession} />
        </ActionList.Item>
      </>
    )
  }

  if (sessionsData.length === 0) {
    return <ActionList.Item disabled>No sessions to display</ActionList.Item>
  }

  const sessionLinks: React.ReactElement[] = sessionsData.map((session, i) => {
    const sessionTitle = session.name?.trim() !== '' ? session.name : `Session ${i + 1}`
    return (
      <ActionList.Item
        key={session.id}
        aria-labelledby={`session-${i + 1}`}
        onSelect={() => onSessionChange(session.id)}
        aria-current={activeSessionId === session.id}
        active={activeSessionId === session.id}
        title={sessionTitle}
      >
        <ActionList.LeadingVisual>{getSessionStatusIcon(session.state)}</ActionList.LeadingVisual>
        <div id={`session-${i + 1}`} className={styles.sessionNavTitle}>
          {sessionTitle}
        </div>
        <ActionList.TrailingVisual role="timer">
          <SessionElapsedTime
            createdAt={session.created_at}
            completedAt={session.completed_at ?? ''}
            state={session.state}
          />
        </ActionList.TrailingVisual>
      </ActionList.Item>
    )
  })

  const premiumRequestCount = sessionsData.reduce((accumulator, sessionData) => {
    return accumulator + sessionData.premium_requests
  }, 0)
  const numberSessions = sessionsData.length
  return (
    <>
      {sessionLinks}
      <ActionList.Divider />
      <ActionList.LinkItem href="https://docs.github.com/copilot/concepts/about-copilot-coding-agent#copilot-coding-agent-usage-costs">
        <span className="text-semibold">{premiumRequestCount} </span>
        <span className="fgColor-muted">
          premium {pluralize('request', premiumRequestCount)} used in {numberSessions}{' '}
          {pluralize('session', numberSessions)}
        </span>

        <ActionList.TrailingVisual>
          <InfoIcon />
        </ActionList.TrailingVisual>
      </ActionList.LinkItem>
    </>
  )
}

export function SessionsNav({
  onSessionChange,
  sessionsData,
  sessionsIsError,
  sessionsIsLoading,
  activeSessionId,
}: SessionsNavProps) {
  return (
    <div aria-live="polite">
      <ActionList className={styles.stepsList}>
        <ActionList.Group>
          <ActionList.GroupHeading as="h3">Sessions</ActionList.GroupHeading>
          <SessionList
            sessionsData={sessionsData}
            sessionsIsLoading={sessionsIsLoading}
            onSessionChange={onSessionChange}
            activeSessionId={activeSessionId}
          />
          {sessionsIsError && (
            <ActionList.Item loading>
              <ActionList.LeadingVisual>
                <AlertIcon />
              </ActionList.LeadingVisual>
              Error loading sessions
              <ActionList.Description variant="block">Retrying automatically…</ActionList.Description>
            </ActionList.Item>
          )}
        </ActionList.Group>
      </ActionList>
    </div>
  )
}
export default SessionsNav
