import {PageLayout} from '@primer/react'
import {SessionsHeader} from './SessionsHeader'
import {SessionContent} from '../session-logs/SessionContent'
import {SessionsNav} from './SessionsNav'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {sessionRoute} from '../../routes/session'
import {useState} from 'react'
import {updateUrl} from '@github-ui/history'
import {useSessions} from '../../hooks/useSessions'
import {SessionContextProvider} from '../../contexts/SessionContext'
import {CurrentRepositoryProvider, useCurrentRepository} from '@github-ui/current-repository'
import {DeprecatedPullContextProvider, useDeprecatedPullContext} from '../../contexts/DeprecatedPullContext'
import type {Session} from '../../types/session'
import {ConsecutiveCAPI401sProvider} from '../../contexts/ConsecutiveCAPI401sContext'
import {CurrentUserProvider} from '@github-ui/current-user'
import {ChatStreamProvider} from '../../contexts/ChatStreamContext'
import type {PublicUser} from '../../types/public-user'
import {useSessionOwners} from '../../hooks/useSessionOwners'

function SessionsLayout({
  initialSessions,
  initialActiveSessionId,
  initialSessionOwners,
  sessionsPollingInterval,
  logsPollingInterval,
  showCopilotCodingAgentPremiumRequestsBanner,
}: {
  initialSessions: Session[]
  initialActiveSessionId: string
  initialSessionOwners: PublicUser[]
  sessionsPollingInterval: number
  logsPollingInterval: number
  showCopilotCodingAgentPremiumRequestsBanner: boolean
}) {
  const [activeSessionId, setActiveSessionId] = useState<string>(initialActiveSessionId)
  const {
    pull: {number: pullNumber, id: pullId},
  } = useDeprecatedPullContext()
  const {
    data: sessionsData,
    isLoading: sessionsIsLoading,
    isError: sessionsIsError,
  } = useSessions({
    pullId,
    initialData: initialSessions,
    sessionsPollingInterval,
  })
  const {data: sessionOwners = []} = useSessionOwners({
    sessions: sessionsData,
    initialData: initialSessionOwners,
  })

  const {ownerLogin, name: repoName} = useCurrentRepository()

  const handleSessionChange = (id: string) => {
    setActiveSessionId(id)
    updateUrl(`/${ownerLogin}/${repoName}/pull/${pullNumber}/agent-sessions/${id}`)
    window.scrollTo({top: 0, behavior: 'auto'})
  }

  const activeSession = sessionsData?.find(session => session.id === activeSessionId)
  const activeSessionOwner = sessionOwners.find(owner => owner.id === activeSession?.user_id)

  return (
    <PageLayout containerWidth="full" padding="none" columnGap="none" rowGap="none">
      <PageLayout.Header padding="none" className="tmp-px-4 tmp-pt-4 pb-0">
        <SessionsHeader />
      </PageLayout.Header>
      <PageLayout.Pane
        position="start"
        padding="none"
        width="large"
        sticky
        className="tmp-py-4 px-2 pl-md-2 pr-md-0 tmp-py-md-4"
      >
        <SessionsNav
          sessionsData={sessionsData}
          sessionsIsLoading={sessionsIsLoading}
          sessionsIsError={sessionsIsError}
          onSessionChange={handleSessionChange}
          activeSessionId={activeSessionId}
        />
      </PageLayout.Pane>
      <PageLayout.Content as="div" padding="none" className="px-2 py-0 tmp-p-md-4 tmp-pl-md-0">
        {activeSession ? (
          <SessionContextProvider session={activeSession} sessionOwner={activeSessionOwner}>
            <ChatStreamProvider>
              <SessionContent
                logsPollingInterval={logsPollingInterval}
                showCopilotCodingAgentPremiumRequestsBanner={showCopilotCodingAgentPremiumRequestsBanner}
              />
            </ChatStreamProvider>
          </SessionContextProvider>
        ) : (
          // TODO: Improve loading state
          <div>Loading...</div>
        )}
      </PageLayout.Content>
    </PageLayout>
  )
}

export function SessionView() {
  const payload = useRouteQuery(sessionRoute, 'mainQuery')

  return (
    <CurrentRepositoryProvider repository={payload.data.repository}>
      <DeprecatedPullContextProvider pull={payload.data.pull}>
        <CurrentUserProvider user={payload.data.currentUser}>
          <ConsecutiveCAPI401sProvider>
            <SessionsLayout
              initialSessions={payload.data.sessions}
              initialActiveSessionId={payload.data.activeSessionId}
              sessionsPollingInterval={payload.data.pollingIntervals.sessionsPollingInterval}
              logsPollingInterval={payload.data.pollingIntervals.logsPollingInterval}
              showCopilotCodingAgentPremiumRequestsBanner={payload.data.showCopilotCodingAgentPremiumRequestsBanner}
              initialSessionOwners={payload.data.sessionOwners}
            />
          </ConsecutiveCAPI401sProvider>
        </CurrentUserProvider>
      </DeprecatedPullContextProvider>
    </CurrentRepositoryProvider>
  )
}
